(x, y, t) => {
  const warp = (px, py, s) => [
    Math.sin(py * 0.025 * s + t * 0.4) * 18 * s + Math.cos(px * 0.018 * s - t * 0.3) * 12 * s,
    Math.cos(px * 0.022 * s - t * 0.35) * 16 * s + Math.sin(py * 0.02 * s + t * 0.45) * 11 * s
  ];
  const [w1x, w1y] = warp(x, y, 1);
  const [w2x, w2y] = warp(x + w1x, y + w1y, 0.7);
  const [w3x, w3y] = warp(x + w1x + w2x, y + w1y + w2y, 0.4);
  const sx = x + w1x + w2x + w3x, sy = y + w1y + w2y + w3y;
  const src = [
    [120+Math.sin(t*0.5)*80, 80+Math.cos(t*0.4)*40, 0.07, 1.8, 1.0],
    [360+Math.cos(t*0.45)*90, 60+Math.sin(t*0.6)*50, 0.09, 1.6, 0.8],
    [240+Math.sin(t*0.35+2)*120, 120+Math.cos(t*0.5+1)*70, 0.05, 2.1, 1.2],
    [80+Math.cos(t*0.7+1)*60, 180+Math.sin(t*0.55+3)*50, 0.11, 1.4, 0.9],
    [400+Math.sin(t*0.4+4)*70, 180+Math.cos(t*0.8+2)*60, 0.06, 2.4, 1.1],
    [200+Math.cos(t*0.3+5)*100, 200+Math.sin(t*0.5)*60, 0.08, 1.9, 0.7],
    [300+Math.sin(t*0.65)*50, 30+Math.cos(t*0.75)*30, 0.1, 2.0, 1.0],
    [40+Math.cos(t*0.55+2)*40, 140+Math.sin(t*0.45)*40, 0.085, 1.7, 0.85]
  ];
  let act = 0, inh = 0, act2 = 0;
  for (const [sX, sY, f, sp, a] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    act += Math.sin(d*f - t*sp) * a;
    inh += Math.sin(d*f*0.75 + t*sp*0.55 + 1.2) * a;
    act2 += Math.sin(d*f*1.3 - t*sp*0.8 + 2.5) * a * 0.5;
  }
  act /= 8; inh /= 8; act2 /= 8;
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.7) + Math.sin(sx*0.025-sy*0.035+t*0.9)*0.7 + Math.sin((sx+sy)*0.08+t*1.8)*0.4 + Math.sin((sx-sy)*0.06-t*1.5)*0.3 + Math.sin(sx*0.06+sy*0.08-t*2.2)*0.2) / 2.6;
  const cx = 240, cy = 120, dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.04-ang*4-t*1.3) + Math.sin(dist*0.06+ang*3-t*0.9)*0.6) * 0.35;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.25 + spiral) * 2.5);
  const rd2 = Math.tanh((act2 - act*0.4 + inh*0.3 - bg*0.2 + spiral*0.5) * 2.0);
  const rd = rd1*0.7 + rd2*0.3;
  const cell = Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12) + Math.sin((sx+sy)*0.08+t*0.5)*0.4) * 1.8) * 0.25;
  const fine = Math.sin(sx*0.3+sy*0.25+t*3) * Math.sin(sx*0.2-sy*0.3-t*2.5) * 0.08;
  const v = (rd*0.7 + cell*0.2 + fine) * 0.5 + 0.5;
  const pal = [[5,12,55],[10,40,85],[15,75,105],[20,130,130],[80,175,145],[180,200,120],[220,170,80],[215,120,75],[180,70,85],[120,35,70],[60,18,55],[20,12,50],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const r = pal[i][0]+(pal[i+1][0]-pal[i][0])*f, g = pal[i][1]+(pal[i+1][1]-pal[i][1])*f, b = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.85+Math.sin(rd*Math.PI)*0.15;
  const edge = Math.abs(rd)>0.65 ? 1.0+(Math.abs(rd)-0.65)*0.8 : 1.0;
  const vig = 1.0 - Math.pow(dist/350, 2)*0.3;
  return [Math.min(255, r*lum*edge*vig)|0, Math.min(255, g*lum*edge*vig)|0, Math.min(255, b*lum*edge*vig)|0];
}
